class Solution{int skip[10][10]{},vis[10]{};int f(int cur,int left){if(!left)return 1;vis[cur]=1;int r=0;for(int n=1;n<=9;n++)if(!vis[n]&&(!skip[cur][n]||vis[skip[cur][n]]))r+=f(n,left-1);vis[cur]=0;return r;}public:int numberOfPatterns(int m,int n){int p[][3]={{1,3,2},{1,7,4},{3,9,6},{7,9,8},{1,9,5},{3,7,5},{4,6,5},{2,8,5}};for(auto&x:p)skip[x[0]][x[1]]=skip[x[1]][x[0]]=x[2];int r=0;for(int l=m;l<=n;l++)r+=4*f(1,l-1)+4*f(2,l-1)+f(5,l-1);return r;}};
